CREATE TABLE schema_version(version INTEGER NOT NULL);
INSERT INTO schema_version VALUES(1);
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,icon TEXT,color TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE series(id TEXT PRIMARY KEY,category_id TEXT,title TEXT NOT NULL,description TEXT,cover_path TEXT,source_type TEXT,source_url TEXT,source_playlist_id TEXT,author TEXT,total_items INTEGER NOT NULL DEFAULT 0,completed_items INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE series_items(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,title TEXT NOT NULL,file_path TEXT,source_url TEXT,source_video_id TEXT,source_playlist_index INTEGER,duration_ms INTEGER,sort_order INTEGER NOT NULL DEFAULT 0,thumbnail_path TEXT,download_task_id TEXT,available INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(series_id) REFERENCES series(id) ON DELETE CASCADE);
CREATE TABLE playback_progress(item_id TEXT PRIMARY KEY,position_ms INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,playback_rate REAL NOT NULL DEFAULT 1.0,last_played_at INTEGER,updated_at INTEGER NOT NULL,FOREIGN KEY(item_id) REFERENCES series_items(id) ON DELETE CASCADE);
CREATE TABLE video_notes(id TEXT PRIMARY KEY,item_id TEXT NOT NULL,time_ms INTEGER NOT NULL,content TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(item_id) REFERENCES series_items(id) ON DELETE CASCADE);
CREATE INDEX idx_series_category ON series(category_id);
CREATE INDEX idx_items_series ON series_items(series_id);
CREATE INDEX idx_items_source_video ON series_items(source_video_id);
CREATE INDEX idx_items_playlist_index ON series_items(series_id,source_playlist_index);
CREATE INDEX idx_progress_last_played ON playback_progress(last_played_at);
CREATE INDEX idx_notes_item ON video_notes(item_id);
ALTER TABLE series ADD COLUMN favorite INTEGER NOT NULL DEFAULT 0;
 ALTER TABLE series ADD COLUMN sort_order INTEGER NOT NULL DEFAULT 0;
 ALTER TABLE series_items ADD COLUMN file_key TEXT;
 ALTER TABLE series_items ADD COLUMN source_key TEXT;
 ALTER TABLE series_items ADD COLUMN download_request TEXT;
 ALTER TABLE series_items ADD COLUMN download_state TEXT NOT NULL DEFAULT 'waiting';
 CREATE UNIQUE INDEX idx_items_file_key ON series_items(series_id,file_key) WHERE file_key IS NOT NULL;
 CREATE UNIQUE INDEX idx_items_source_key ON series_items(series_id,source_key) WHERE source_key IS NOT NULL;
 CREATE INDEX idx_items_task ON series_items(download_task_id);
 CREATE TABLE learning_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 UPDATE schema_version SET version=2;
ALTER TABLE playback_progress ADD COLUMN last_sequence INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER learning_item_insert AFTER INSERT ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=NEW.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=NEW.series_id AND p.completed=1) WHERE id=NEW.series_id; END;
CREATE TRIGGER learning_item_delete AFTER DELETE ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=OLD.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=OLD.series_id AND p.completed=1) WHERE id=OLD.series_id; END;
CREATE TRIGGER learning_item_move AFTER UPDATE OF series_id ON series_items BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=OLD.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=OLD.series_id AND p.completed=1) WHERE id=OLD.series_id;UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=NEW.series_id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=NEW.series_id AND p.completed=1) WHERE id=NEW.series_id; END;
CREATE TRIGGER learning_progress_insert AFTER INSERT ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=NEW.item_id); END;
CREATE TRIGGER learning_progress_update AFTER UPDATE OF completed ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=NEW.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=NEW.item_id); END;
CREATE TRIGGER learning_progress_delete AFTER DELETE ON playback_progress BEGIN UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items WHERE series_id=(SELECT series_id FROM series_items WHERE id=OLD.item_id)),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=(SELECT series_id FROM series_items WHERE id=OLD.item_id) AND p.completed=1) WHERE id=(SELECT series_id FROM series_items WHERE id=OLD.item_id); END;
UPDATE series SET total_items=(SELECT COUNT(*) FROM series_items i WHERE i.series_id=series.id),completed_items=(SELECT COUNT(*) FROM series_items i JOIN playback_progress p ON p.item_id=i.id WHERE i.series_id=series.id AND p.completed=1);
UPDATE schema_version SET version=3;

ALTER TABLE series_items ADD COLUMN request_key TEXT; CREATE INDEX idx_learning_request_key ON series_items(request_key); UPDATE schema_version SET version=4;
ALTER TABLE series_items ADD COLUMN thumbnail_source TEXT CHECK(thumbnail_source IS NULL OR thumbnail_source IN ('manual','remote','generated','series','placeholder'));
ALTER TABLE series_items ADD COLUMN source_thumbnail_url TEXT;
ALTER TABLE series_items ADD COLUMN thumbnail_key TEXT;
UPDATE series_items SET source_thumbnail_url=thumbnail_path,thumbnail_path=NULL WHERE lower(thumbnail_path) LIKE 'http://%' OR lower(thumbnail_path) LIKE 'https://%';
UPDATE series_items SET thumbnail_source='manual' WHERE thumbnail_path IS NOT NULL;
UPDATE schema_version SET version=5;
